const strengthDemos={A:[['arms','squat'],['squat'],['press','push'],['row'],['bridge'],['suitcase']],B:[['arms','squat'],['split'],['push'],['row'],['calf'],['deadbug']]};
const weekDemos=[['scan','wall'],['receive','wall'],['feint'],['shield'],['behind','wide'],['cutback'],['transition'],['feint','shield']];
data.demoChecks=data.demoChecks||{};
const demoStyle=document.createElement('style');demoStyle.textContent='.demo{background:#f4f2fb;border-radius:12px;padding:10px 14px}.demo iframe{width:100%;aspect-ratio:16/9;border:0;border-radius:9px;background:#101b30}.demo .source{font-size:12px;color:#61708a}.logtable{width:100%;border-collapse:collapse;font-size:14px}.logtable td,.logtable th{text-align:left;padding:12px 6px;border-bottom:1px solid #dfe5ef;vertical-align:top}.logtable th{font-size:12px}.logtable caption{text-align:left;font-weight:bold;margin-bottom:8px}#historyArea{overflow-wrap:anywhere}.demo a{display:inline-block;margin:8px 0}.demo label{display:block;margin-top:10px}';document.head.appendChild(demoStyle);
const historyButton=document.createElement('button');historyButton.dataset.history='true';historyButton.textContent='History';$('sections').appendChild(historyButton);const historyArea=document.createElement('section');historyArea.id='historyArea';historyArea.hidden=true;$('learningArea').after(historyArea);
const info=document.createElement('details');info.innerHTML='<summary>Who can see my log?</summary><p>Checkoffs, weights, feelings and learning notes save automatically in this browser on this device. You can review them in History. A parent using this same device can switch profiles and review both boys.</p><p>Profiles are not private accounts: anyone with access to this browser can switch between them. Nothing syncs to a parent’s phone, and there is no remote parent dashboard. Clearing browser data can erase the log.</p><p>Sets and videos are self-reported. Checking a set means you completed the target on its card; the app does not count your actual reps. Timer time and video viewing time are not logged. Use Download my training log for a backup, or Copy summary in History to share manually.</p>';$('profiles').after(info);
function videoHTML(key){const d=demoCatalog[key];if(!d)throw new Error('Missing demo: '+key);const check=player+'|'+key;const watched=data.demoChecks[check];const url=d.url||'https://www.youtube.com/watch?v='+d.yt;return '<details class="demo" data-demo="'+key+'"><summary>▶ Watch first: '+escapeHTML(d.title)+'</summary><p class="source">'+escapeHTML(d.by)+'</p><p>'+escapeHTML(d.cue)+'</p>'+(d.yt?'<div class="videoSlot" data-youtube="'+d.yt+'" data-title="'+escapeHTML(d.title)+'"></div>':'')+'<a href="'+url+'" target="_blank" rel="noopener">'+(d.yt?'Open video on YouTube':'Open video on the creator’s page')+' ↗</a><p class="source">Follow this app’s reps, time and beginner version. A demonstration does not replace an adult checking your form. If the player is blocked, use the link above.</p><label><input type="checkbox" data-demo-check="'+key+'" '+(watched?'checked':'')+'> I watched and understand this demonstration</label></details>'}
function injectDemos(){if(section==='strength'){document.querySelectorAll('#cards .exercise').forEach((card,i)=>{if(card.querySelector('.demo'))return;card.querySelector('p').insertAdjacentHTML('afterend',strengthDemos[day][i].map(videoHTML).join(''))})}else if(section==='soccer'){const all=[['touches'],weekDemos[data.weeks[player]-1],ballDay==='A'?[partner?'combine':'move']:['feint','cutback']];document.querySelectorAll('#learningArea .exercise').forEach((card,i)=>{if(card.querySelector('.demo'))return;card.querySelector('p').insertAdjacentHTML('afterend',all[i].map(videoHTML).join(''))})}else if(section==='watch'){const card=$('learningArea').querySelector('.exercise');if(card&&!card.querySelector('.demo'))card.querySelector('p').insertAdjacentHTML('afterend',weekDemos[data.weeks[player]-1].map(videoHTML).join(''))}}
function historyRows(){const rows=[];for(const [k,r] of Object.entries(data.records)){const [p,date,work]=k.split('|');if(Number(p)!==player)continue;const checks=Object.values(r.checks).filter(Boolean).length;if(!checks&&!r.feeling&&!Object.values(r.weights).some(v=>v!==''))continue;const weights=Object.entries(r.weights).filter(([,v])=>v!=='').map(([i,v])=>(workouts[work]?.[i]?.[0]||'Exercise')+': '+v+' lb').join('; ');rows.push({date,title:'Strength '+work,detail:checks+' items checked'+(r.feeling?' · '+r.feeling:'')+(weights?' · '+weights:'')})}for(const [k,r] of Object.entries(data.learning)){const parts=k.split('|');if(Number(parts[0])!==player)continue;const checks=Object.values(r.checks).filter(Boolean).length;if(!checks&&!r.note)continue;const watch=parts[1].startsWith('week-');rows.push({date:watch?'Week '+parts[1].slice(5):parts[1],title:watch?'Watch & learn':'Soccer '+parts[2],detail:checks+' items checked'+(r.note?' · '+r.note:'')})}return rows.sort((a,b)=>b.date.localeCompare(a.date))}
function historyRender(){const rows=historyRows();$('historyArea').innerHTML='<section class="panel"><h2>'+escapeHTML(data.names[player])+' • History</h2><p class="note">This device only. Switch Player 1 / Player 2 above to review the other local profile. These are checkoffs, not verified reps or video watch time.</p><button id="copySummary">Copy summary</button><div id="summaryStatus" class="status" role="status"></div>'+(rows.length?'<table class="logtable"><thead><tr><th>Date / week</th><th>Activity</th><th>Recorded work</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+escapeHTML(r.date)+'</td><td>'+escapeHTML(r.title)+'</td><td>'+escapeHTML(r.detail)+'</td></tr>').join('')+'</tbody></table>':'<p>No work logged on this device yet. Check off a completed set or drill to start your history.</p>')+'<details><summary>Demonstrations marked understood</summary>'+Object.entries(data.demoChecks).filter(([k,v])=>k.startsWith(player+'|')&&v).map(([k,v])=>'<p>'+escapeHTML(demoCatalog[k.split('|')[1]]?.title||k)+' · '+escapeHTML(new Date(v).toLocaleDateString())+'</p>').join('')+'</details></section>';$('copySummary').onclick=async()=>{const summary=data.names[player]+' — training log (this device)\n'+rows.map(r=>r.date+' | '+r.title+' | '+r.detail).join('\n');try{await navigator.clipboard.writeText(summary);$('summaryStatus').textContent='Copied. Paste into a message to share; nothing was sent automatically.'}catch{$('summaryStatus').textContent='Copy is unavailable. Use the downloadable log from Strength.'}}}
const baseLearnRender=learnRender;learnRender=function(){if(section==='history'){$('learningArea').hidden=true;$('strengthArea').hidden=true;$('historyArea').hidden=false;document.querySelectorAll('[data-section]').forEach(b=>b.classList.remove('active'));historyButton.classList.add('active');historyRender();return}$('historyArea').hidden=true;historyButton.classList.remove('active');baseLearnRender();injectDemos()};
document.addEventListener('click',e=>{if(e.target.closest('[data-history]')){pause();section='history';render()}});
document.addEventListener('toggle',e=>{if(!e.target.matches?.('details.demo')||!e.target.open)return;pause();const slot=e.target.querySelector('.videoSlot');if(slot&&!slot.firstChild){const frame=document.createElement('iframe');frame.src='https://www.youtube-nocookie.com/embed/'+slot.dataset.youtube+'?rel=0&playsinline=1';frame.title=slot.dataset.title;frame.allow='encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';slot.appendChild(frame)}},true);
document.addEventListener('change',e=>{if(e.target.dataset.demoCheck){const k=player+'|'+e.target.dataset.demoCheck;if(e.target.checked)data.demoChecks[k]=new Date().toISOString();else delete data.demoChecks[k];persist()}});
$('export').onclick=()=>{const selected=obj=>Object.fromEntries(Object.entries(obj).filter(([k])=>k.startsWith(player+'|')));const out={player:data.names[player],exported:new Date().toISOString(),scope:'This browser/device only; self-reported completion. Timer and actual repetitions are not tracked.',strength:selected(data.records),soccerAndLearning:selected(data.learning),demonstrations:selected(data.demoChecks)};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));a.download='galaxy-'+data.names[player].replace(/[^a-z0-9]/gi,'-')+'-training-log.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
render();
